--
-- Name: ai_work_admission(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ai_work_admission() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  ws uuid;
  policy record;
BEGIN
  IF TG_TABLE_NAME = 'proactive_comparison_outbox' THEN
    SELECT workspace_id INTO ws FROM projects WHERE id = NEW.project_id;
  ELSIF TG_TABLE_NAME = 'assistant_reaction_events' THEN
    SELECT workspace_id INTO ws FROM assistant_reactions WHERE id = NEW.reaction_id;
  ELSE
    ws := NEW.workspace_id;
  END IF;
  SELECT state, epoch INTO policy FROM workspace_ai_policies WHERE workspace_id = ws FOR SHARE;
  IF NOT FOUND OR policy.state <> 'allowed' OR NEW.ai_epoch IS DISTINCT FROM policy.epoch THEN
    RAISE EXCEPTION 'AI is turned off in this workspace' USING ERRCODE = 'FX403', HINT = 'WORKSPACE_AI_BLOCKED';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: assistant_capture_reaction(uuid, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assistant_capture_reaction(p_project uuid, p_owner text, p_event text, p_object uuid, p_source uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  policy record;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM assistant_reactions WHERE enabled AND project_id=p_project AND owner_user_id=p_owner AND event=p_event) THEN
    RETURN;
  END IF;
  SELECT a.state, a.epoch INTO policy FROM workspace_ai_policies a JOIN projects p ON p.workspace_id = a.workspace_id
    WHERE p.id = p_project FOR SHARE OF a;
  IF NOT FOUND OR policy.state <> 'allowed' THEN
    RETURN;
  END IF;
  INSERT INTO assistant_reaction_events(reaction_id,owner_user_id,object_id,source_id,action,event,reaction_version,state,ai_epoch)
  SELECT id,p_owner,p_object,p_source,action,event,version,CASE WHEN p_event='pr_ready' THEN 'proof' ELSE 'queued' END,policy.epoch
  FROM assistant_reactions WHERE enabled AND project_id=p_project AND owner_user_id=p_owner AND event=p_event
  ON CONFLICT DO NOTHING;
END $$;


--
-- Name: assistant_mention_reaction_tap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assistant_mention_reaction_tap() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.source_type='project' AND NEW.reason IN ('mention','question') AND NEW.url ~ '/conversations/[0-9a-f-]+#message-[0-9a-f-]+' THEN
  PERFORM assistant_capture_reaction(NEW.source_id,NEW.user_id,'mentioned',NEW.id,NEW.id);
 END IF;
 RETURN NEW;
END $$;


--
-- Name: assistant_pr_reaction_tap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assistant_pr_reaction_tap() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE person text; source uuid := gen_random_uuid();
BEGIN
 IF NEW.state='current' AND NEW.facts->>'execution'='ready_for_review'
 AND (TG_OP='INSERT' OR OLD.facts->>'execution' IS DISTINCT FROM 'ready_for_review' OR OLD.facts->>'headSha' IS DISTINCT FROM NEW.facts->>'headSha')
 AND EXISTS(SELECT 1 FROM github_bindings WHERE id=NEW.binding_id AND state='active') THEN
  SELECT owner_user_id INTO person FROM project_work_items WHERE id=NEW.task_id AND project_id=NEW.project_id;
  IF person IS NOT NULL THEN PERFORM assistant_capture_reaction(NEW.project_id,person,'pr_ready',NEW.task_id,source);
  UPDATE assistant_reaction_events SET data=jsonb_build_object('linkId',NEW.id) WHERE source_id=source; END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: assistant_result_reaction_tap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assistant_result_reaction_tap() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE person text;
BEGIN
 IF NEW.from_type='result' AND NEW.to_type='work' AND EXISTS(SELECT 1 FROM project_results WHERE id=NEW.from_id AND finding='negative' AND project_id=NEW.project_id) THEN
  SELECT owner_user_id INTO person FROM project_work_items WHERE id=NEW.to_id AND project_id=NEW.project_id;
  IF person IS NOT NULL THEN PERFORM assistant_capture_reaction(NEW.project_id,person,'failed_result',NEW.to_id,NEW.from_id); END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: assistant_task_reaction_tap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assistant_task_reaction_tap() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
 IF NEW.owner_user_id IS NOT NULL THEN
  IF TG_OP='INSERT' OR OLD.owner_user_id IS DISTINCT FROM NEW.owner_user_id THEN
   PERFORM assistant_capture_reaction(NEW.project_id,NEW.owner_user_id,'assigned',NEW.id,gen_random_uuid());
  END IF;
  IF NEW.status='blocked' AND (TG_OP='INSERT' OR OLD.status IS DISTINCT FROM NEW.status OR OLD.blocker IS DISTINCT FROM NEW.blocker) THEN
   PERFORM assistant_capture_reaction(NEW.project_id,NEW.owner_user_id,'blocked',NEW.id,gen_random_uuid());
  END IF;
 END IF;
 RETURN NEW;
END $$;


--
-- Name: cowork_stop_connection_units(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cowork_stop_connection_units() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND (NEW.revoked_at IS NULL OR OLD.revoked_at IS NOT NULL) THEN
    RETURN NEW;
  END IF;
  -- The parent connection row is already exclusively locked by UPDATE/DELETE.
  PERFORM connection_id FROM cowork_connection_slots
    WHERE connection_id = OLD.id ORDER BY connection_id FOR UPDATE;
  PERFORM id FROM project_work_items
    WHERE id IN (SELECT work_id FROM cowork_units WHERE assignment_connection_id = OLD.id
      AND state NOT IN ('completed', 'stopped')) ORDER BY id FOR UPDATE;
  PERFORM id FROM cowork_units WHERE assignment_connection_id = OLD.id
    AND state NOT IN ('completed', 'stopped') ORDER BY id FOR UPDATE;
  UPDATE cowork_units SET state = 'stopped', generation = generation + 1, version = version + 1,
    lease_id = NULL, lease_session_id = NULL, lease_expires_at = NULL, updated_at = clock_timestamp()
    WHERE assignment_connection_id = OLD.id AND state NOT IN ('completed', 'stopped');
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: dm_messages_flat_thread(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dm_messages_flat_thread() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.thread_root_id IS NOT NULL AND EXISTS (SELECT 1 FROM dm_messages r WHERE r.id = NEW.thread_root_id AND r.thread_root_id IS NOT NULL) THEN
    RAISE EXCEPTION 'a reply cannot be the root of another thread' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: flux_agent_pause_follows_hold(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_agent_pause_follows_hold() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  DELETE FROM agent_pauses p WHERE p.task_id = NEW.id
    AND (NEW.owner_agent_id IS DISTINCT FROM p.agent_id OR NEW.status IN ('done', 'not_pursued') OR NEW.parked_at IS NOT NULL);
  RETURN NULL;
END $$;


--
-- Name: flux_agent_thread_human_boundary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_agent_thread_human_boundary() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE thread project_conversations%ROWTYPE;
BEGIN
  SELECT * INTO thread FROM project_conversations WHERE id = NEW.conversation_id AND space = 'agents';
  IF FOUND AND NEW.author_id IS NOT NULL AND EXISTS (SELECT 1 FROM agent_thread_guard_events WHERE task_id = thread.work_id) THEN
    INSERT INTO agent_thread_guard_events(workspace_id, project_id, task_id, conversation_id, message_id, kind, turn_count, transaction_id)
      VALUES(thread.workspace_id, thread.project_id, thread.work_id, thread.id, NEW.id, 'human_message', 0, txid_current());
  END IF;
  RETURN NULL;
END $$;


--
-- Name: flux_append_agent_thread_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_append_agent_thread_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE previous integer;
BEGIN
  PERFORM 1 FROM project_work_items WHERE id=NEW.task_id AND workspace_id=NEW.workspace_id
    AND project_id=NEW.project_id AND creation_reverted_at IS NULL FOR UPDATE;
  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM project_conversations WHERE id=NEW.conversation_id
    AND workspace_id=NEW.workspace_id AND project_id=NEW.project_id AND space='agents' AND work_id=NEW.task_id) THEN
    RAISE EXCEPTION 'Invalid task-thread guard scope' USING ERRCODE='23514',CONSTRAINT='agent_thread_guard_scope';
  END IF;
  SELECT turn_count INTO previous FROM (
    SELECT sequence,turn_count FROM agent_thread_guard_events WHERE task_id=NEW.task_id
    UNION ALL SELECT sequence,0 FROM agent_thread_artifact_resets WHERE task_id=NEW.task_id AND sequence IS NOT NULL
  ) boundaries ORDER BY sequence DESC LIMIT 1;
  IF NEW.kind='agent_message' THEN
    IF COALESCE(previous,0)>=5 THEN RAISE EXCEPTION 'AGENT_THREAD_TURN_LIMIT' USING ERRCODE='23514',CONSTRAINT='agent_thread_turn_limit'; END IF;
    NEW.turn_count:=COALESCE(previous,0)+1;
  ELSE
    IF pg_trigger_depth()<2 OR NOT EXISTS(SELECT 1 FROM project_messages WHERE id=NEW.message_id
      AND conversation_id=NEW.conversation_id AND workspace_id=NEW.workspace_id AND project_id=NEW.project_id
      AND author_id IS NOT NULL AND author_agent_id IS NULL) THEN
      RAISE EXCEPTION 'Invalid human reset boundary' USING ERRCODE='23514',CONSTRAINT='agent_thread_guard_reset';
    END IF;
    NEW.turn_count:=0;
  END IF;
  NEW.sequence:=nextval('agent_thread_guard_sequence');NEW.transaction_id:=txid_current();RETURN NEW;
END $$;


--
-- Name: flux_append_artifact_reset(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_append_artifact_reset() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE boundary agent_thread_artifact_boundaries%ROWTYPE;
BEGIN
  SELECT * INTO boundary FROM agent_thread_artifact_boundaries WHERE id=NEW.boundary_id;
  IF NOT FOUND OR boundary.workspace_id<>NEW.workspace_id OR boundary.project_id<>NEW.project_id
    OR boundary.transaction_id<>txid_current() THEN
    RAISE EXCEPTION 'An old or foreign artifact boundary cannot reset a task'
      USING ERRCODE='23514',CONSTRAINT='agent_thread_artifact_boundary';
  END IF;
  PERFORM 1 FROM project_work_items WHERE id=NEW.task_id AND workspace_id=NEW.workspace_id
    AND project_id=NEW.project_id AND creation_reverted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Invalid artifact reset task' USING ERRCODE='23514',CONSTRAINT='agent_thread_artifact_scope'; END IF;
  IF NOT flux_artifact_task_is_direct(NEW.task_id,boundary) THEN
    RAISE EXCEPTION 'The task is not a direct eligible artifact recipient'
      USING ERRCODE='23514',CONSTRAINT='agent_thread_artifact_association';
  END IF;
  NEW.sequence:=nextval('agent_thread_guard_sequence');
  NEW.content_identity:=CASE WHEN boundary.kind='file' THEN boundary.content_identity ELSE NULL END;
  RETURN NEW;
END $$;


SET LOCAL default_tablespace = '';

SET LOCAL default_table_access_method = heap;

--
-- Name: agent_thread_artifact_boundaries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_thread_artifact_boundaries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    workspace_id uuid NOT NULL,
    project_id uuid NOT NULL,
    kind text NOT NULL,
    source_id text NOT NULL,
    revision text NOT NULL,
    content_identity text,
    transaction_id bigint NOT NULL,
    CONSTRAINT agent_thread_artifact_boundaries_kind_check CHECK ((kind = ANY (ARRAY['doc'::text, 'material'::text, 'result'::text, 'decision'::text, 'thought'::text, 'github_pr'::text, 'file'::text])))
);


--
-- Name: flux_artifact_task_is_direct(uuid, public.agent_thread_artifact_boundaries); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_artifact_task_is_direct(task uuid, boundary public.agent_thread_artifact_boundaries) RETURNS boolean
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  IF boundary.kind IN ('doc','material') THEN RETURN EXISTS(SELECT 1 FROM project_object_links l
    WHERE l.workspace_id=boundary.workspace_id AND l.project_id=boundary.project_id AND (
      (l.from_type='work' AND l.from_id=task AND l.to_id::text=boundary.source_id AND l.role IN ('source','related')
        AND ((l.to_type='doc' AND boundary.kind='doc') OR(l.to_type='material' AND(l.to_version IS NULL OR l.to_version::text=boundary.revision))))
      OR(boundary.kind='doc' AND l.from_type='doc' AND l.from_id::text=boundary.source_id AND l.to_type='work' AND l.to_id=task AND l.role IN('mentions','source'))));
  ELSIF boundary.kind='result' THEN RETURN EXISTS(SELECT 1 FROM project_object_links l WHERE l.workspace_id=boundary.workspace_id AND l.project_id=boundary.project_id
    AND l.from_type='result' AND l.from_id::text=boundary.source_id AND l.to_type='work' AND l.to_id=task AND l.role='about');
  ELSIF boundary.kind='decision' THEN RETURN EXISTS(SELECT 1 FROM project_object_links l WHERE l.workspace_id=boundary.workspace_id AND l.project_id=boundary.project_id
    AND l.from_type='decision' AND l.from_id::text=boundary.source_id AND l.to_type='work' AND l.to_id=task AND l.role IN('affects','still_applies'));
  ELSIF boundary.kind='thought' THEN RETURN EXISTS(SELECT 1 FROM project_object_links l JOIN sketch_thoughts t ON t.id=l.to_id JOIN sketches s ON s.id=t.sketch_id
    WHERE l.workspace_id=boundary.workspace_id AND l.project_id=boundary.project_id AND l.from_type='work' AND l.from_id=task AND l.to_type='thought'
      AND l.to_id::text=boundary.source_id AND l.role IN('source','related') AND t.workspace_id=boundary.workspace_id AND s.project_id=boundary.project_id AND s.scope='project');
  ELSIF boundary.kind='file' THEN RETURN EXISTS(SELECT 1 FROM project_files f LEFT JOIN project_messages m ON m.id=f.message_id
    LEFT JOIN project_conversations c ON c.id=m.conversation_id LEFT JOIN project_task_discussions d ON d.conversation_id=c.id
    LEFT JOIN sketch_thoughts t ON t.id=f.thought_id LEFT JOIN sketches s ON s.id=t.sketch_id
    WHERE f.id::text=boundary.source_id AND f.workspace_id=boundary.workspace_id AND f.project_id=boundary.project_id AND(
      (COALESCE(c.work_id,d.work_id)=task AND m.project_id=boundary.project_id AND m.workspace_id=boundary.workspace_id AND c.project_id=boundary.project_id AND c.workspace_id=boundary.workspace_id)
      OR(s.scope='project' AND s.project_id=boundary.project_id AND s.workspace_id=boundary.workspace_id AND EXISTS(SELECT 1 FROM project_object_links l
        WHERE l.workspace_id=boundary.workspace_id AND l.project_id=boundary.project_id AND l.from_type='work' AND l.from_id=task AND l.to_type='thought' AND l.to_id=t.id AND l.role IN('source','related')))));
  ELSE RETURN EXISTS(SELECT 1 FROM github_task_links l JOIN github_bindings b ON b.id=l.binding_id WHERE l.task_id=task AND l.workspace_id=boundary.workspace_id AND l.project_id=boundary.project_id
    AND l.binding_id::text || ':' || b.repository_id || ':' || l.pull_id || ':' || l.task_id::text=boundary.source_id AND l.facts->>'headSha'=boundary.revision AND l.state='current' AND b.state='active');
  END IF;
END $$;


--
-- Name: flux_artifact_xid_is_current(xid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_artifact_xid_is_current(source_xid xid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS(SELECT 1 FROM pg_locks WHERE pid=pg_backend_pid() AND locktype='transactionid'
    AND mode='ExclusiveLock' AND transactionid=source_xid)
$$;


--
-- Name: flux_capture_artifact_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_capture_artifact_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE artifact_kind text;source text;revision_key text;workspace uuid;project uuid;changed boolean;
  previous project_material_versions%ROWTYPE; map sketches%ROWTYPE; binding github_bindings%ROWTYPE;
BEGIN
  workspace:=NEW.workspace_id;
  IF TG_TABLE_NAME='project_material_versions' THEN
    project:=NEW.project_id;source:=NEW.material_id::text;revision_key:=NEW.version::text;
    SELECT kind INTO artifact_kind FROM project_materials WHERE id=NEW.material_id;
    SELECT * INTO previous FROM project_material_versions WHERE material_id=NEW.material_id AND version=NEW.version-1;
    changed:=NOT FOUND OR NEW.body IS DISTINCT FROM previous.body OR NEW.url IS DISTINCT FROM previous.url
      OR (artifact_kind='doc' AND COALESCE(NEW.state,'published') IS DISTINCT FROM COALESCE(previous.state,'published'));
  ELSIF TG_TABLE_NAME='project_results' THEN
    artifact_kind:='result';source:=NEW.id::text;revision_key:='created';project:=NEW.project_id;changed:=true;
  ELSIF TG_TABLE_NAME='project_decisions' THEN
    artifact_kind:='decision';source:=NEW.id::text;revision_key:=NEW.version::text || ':' || NEW.status;project:=NEW.project_id;
    changed:=TG_OP='INSERT' OR NEW.status IS DISTINCT FROM OLD.status;
  ELSIF TG_TABLE_NAME='sketch_thoughts' THEN
    SELECT * INTO map FROM sketches WHERE id=NEW.sketch_id;
    IF map.scope<>'project' OR map.project_id IS NULL THEN RETURN NULL; END IF;
    artifact_kind:='thought';source:=NEW.id::text;revision_key:=NEW.version::text;project:=map.project_id;
    changed:=TG_OP='INSERT' OR NEW.text IS DISTINCT FROM OLD.text;
  ELSIF TG_TABLE_NAME='project_files' THEN
    artifact_kind:='file';source:=NEW.id::text;revision_key:='published';project:=NEW.project_id;
    changed:=OLD.published_at IS NULL AND NEW.published_at IS NOT NULL AND NEW.state='ready' AND NEW.replay_of IS NULL;
  ELSE
    SELECT * INTO binding FROM github_bindings WHERE id=NEW.binding_id;
    artifact_kind:='github_pr';source:=NEW.binding_id::text || ':' || binding.repository_id || ':' || NEW.pull_id || ':' || NEW.task_id::text;
    revision_key:=NEW.facts->>'headSha';project:=NEW.project_id;
    changed:=NEW.state='current' AND binding.state='active' AND revision_key~'^[0-9a-f]{40}([0-9a-f]{24})?$'
      AND (TG_OP='INSERT' OR NEW.facts->>'headSha' IS DISTINCT FROM OLD.facts->>'headSha');
  END IF;
  -- No-op/geometry/status-only and missing/unverified PR heads have no witness.
  IF changed IS DISTINCT FROM true THEN RETURN NULL; END IF;
  INSERT INTO agent_thread_artifact_mutations(kind,source_id,revision,workspace_id,project_id,transaction_id,progress)
    VALUES(artifact_kind,source,revision_key,workspace,project,txid_current(),changed)
    ON CONFLICT(kind,source_id,revision,transaction_id) DO UPDATE
      SET progress=agent_thread_artifact_mutations.progress OR EXCLUDED.progress;
  RETURN NULL;
END $_$;


--
-- Name: flux_complete_agent_thread_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_complete_agent_thread_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.kind = 'agent_message' AND NOT EXISTS (
    SELECT 1 FROM project_messages m JOIN agent_command_receipts r
      ON r.connection_id = NEW.connection_id AND r.client_command_id = NEW.client_command_id
    JOIN agent_runtime_sessions runtime ON runtime.id = r.runtime_session_id AND runtime.connection_id = r.connection_id
    WHERE m.id = NEW.message_id AND m.author_agent_id = NEW.author_agent_id AND m.author_id IS NULL
      AND m.conversation_id = NEW.conversation_id AND m.project_id = NEW.project_id AND m.workspace_id = NEW.workspace_id
      AND runtime.agent_id = NEW.author_agent_id AND runtime.workspace_id = NEW.workspace_id
      AND r.runtime_session_id = NEW.runtime_session_id AND r.grant_id = NEW.grant_id
      AND r.operation = 'conversation.reply' AND r.project_id = NEW.project_id
      AND r.value->>'taskId' = NEW.task_id::text AND r.value->>'conversationId' = NEW.conversation_id::text
      AND r.value->>'messageId' = NEW.message_id::text
      AND r.postconditions @> jsonb_build_array(jsonb_build_object('kind', 'message', 'id', NEW.message_id::text))
  ) THEN
    RAISE EXCEPTION 'Incomplete native task-thread receipt' USING ERRCODE = '23514', CONSTRAINT = 'agent_thread_guard_receipt';
  END IF;
  RETURN NULL;
END $$;


--
-- Name: flux_event_audience_shape(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_event_audience_shape() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
BEGIN
  IF NEW.recipient ~ '^(human|agent):[A-Za-z0-9_-]{1,64}$' THEN RETURN NEW; END IF;
  IF NOT EXISTS (SELECT 1 FROM events e WHERE e.id = NEW.event_id AND e.workspace_id IS NOT NULL AND workspace_sealed(e.workspace_id)) THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'An encrypted workspace''s event audience names principals only' USING ERRCODE = 'FX409', HINT = 'EVENT_CONTENT_REFUSED';
END $_$;


--
-- Name: flux_event_data_free(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_event_data_free() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  v text;
BEGIN
  IF NEW.workspace_id IS NULL OR NOT workspace_sealed(NEW.workspace_id) THEN RETURN NEW; END IF;
  -- The actor and the kind are shapes, never text (#721 review P3-3).
  IF NEW.actor_id !~ '^(human|agent|fixture):[A-Za-z0-9_-]{1,64}$' OR NEW.kind !~ '^[a-z][a-z_]*(\.[a-z][a-z_]*)+\.v[0-9]+$' THEN
    RAISE EXCEPTION 'An encrypted workspace''s event must be content-free' USING ERRCODE = 'FX409', HINT = 'EVENT_CONTENT_REFUSED';
  END IF;
  FOR v IN SELECT k #>> '{}' FROM jsonb_path_query(NEW.data, 'strict $.** ? (@.type() == "object").keyvalue().key') AS k LOOP
    CONTINUE WHEN v = '$sealed';
    CONTINUE WHEN v ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
    CONTINUE WHEN EXISTS (SELECT 1 FROM event_data_keys t WHERE t.key = v);
    RAISE EXCEPTION 'An encrypted workspace''s event must be content-free' USING ERRCODE = 'FX409', HINT = 'EVENT_CONTENT_REFUSED';
  END LOOP;
  FOR v IN SELECT x #>> '{}' FROM jsonb_path_query(NEW.data, 'strict $.**') AS x WHERE jsonb_typeof(x) = 'string' LOOP
    CONTINUE WHEN v ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
    CONTINUE WHEN v ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,9})?(Z|[+-][0-9]{2}:[0-9]{2})$';
    CONTINUE WHEN flux_is_sealed(v);
    CONTINUE WHEN EXISTS (SELECT 1 FROM event_data_tokens t WHERE t.token = v);
    CONTINUE WHEN EXISTS (SELECT 1 FROM auth_users u WHERE u.id::text = v);
    CONTINUE WHEN v LIKE 'human:%' AND EXISTS (SELECT 1 FROM auth_users u WHERE u.id::text = substr(v, 7));
    CONTINUE WHEN v LIKE 'agent:%' AND EXISTS (SELECT 1 FROM agents a WHERE a.id::text = substr(v, 7));
    RAISE EXCEPTION 'An encrypted workspace''s event must be content-free' USING ERRCODE = 'FX409', HINT = 'EVENT_CONTENT_REFUSED';
  END LOOP;
  RETURN NEW;
END $_$;


--
-- Name: flux_events_assign_seq(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_events_assign_seq() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('flux.events.seq'));
  NEW.seq := nextval(pg_get_serial_sequence('events', 'seq'));
  RETURN NEW;
END
$$;


