    PERFORM pg_notify('flux_events', NEW.seq::text);
  END IF;
  RETURN NULL;
END
$$;


--
-- Name: flux_guard_agent_thread_write(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_guard_agent_thread_write() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.author_agent_id IS NOT NULL AND EXISTS (SELECT 1 FROM project_conversations WHERE id = NEW.conversation_id AND space = 'agents')
    AND (TG_OP <> 'INSERT' OR NOT EXISTS (SELECT 1 FROM agent_thread_guard_events g
      WHERE g.message_id = NEW.id AND g.kind = 'agent_message' AND g.transaction_id = txid_current()
        AND g.author_agent_id = NEW.author_agent_id AND g.conversation_id = NEW.conversation_id
        AND g.workspace_id = NEW.workspace_id AND g.project_id = NEW.project_id)) THEN
    RAISE EXCEPTION 'Agent-thread agent writes require the verified internal native guard'
      USING ERRCODE = '23514', CONSTRAINT = 'agent_thread_agent_writes_closed';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: flux_guard_task_creation_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_guard_task_creation_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.creation_baseline_version IS NOT NULL AND
    (NEW.creation_baseline_version IS DISTINCT FROM OLD.creation_baseline_version OR NEW.creation_baseline IS DISTINCT FROM OLD.creation_baseline OR NEW.creation_origin IS DISTINCT FROM OLD.creation_origin
      OR NEW.creation_proposal_id IS DISTINCT FROM OLD.creation_proposal_id) THEN
    RAISE EXCEPTION 'immutable task creation baseline' USING ERRCODE = 'check_violation';
  END IF;
  IF OLD.first_persisted_use_at IS NOT NULL AND NEW.first_persisted_use_at IS DISTINCT FROM OLD.first_persisted_use_at THEN
    RAISE EXCEPTION 'immutable first task use' USING ERRCODE = 'check_violation';
  END IF;
  -- Every column this migration knows; a later migration's own new column can still be backfilled.
  IF OLD.creation_reverted_at IS NOT NULL AND (ROW(NEW.id, NEW.workspace_id, NEW.project_id, NEW.title, NEW.outcome, NEW.status, NEW.blocker,
      NEW.owner_user_id, NEW.owner_agent_id, NEW.parked_by_decision_id, NEW.parked_at, NEW.created_by_kind, NEW.created_by_id,
      NEW.client_command_id, NEW.request_fingerprint, NEW.criteria, NEW.version, NEW.created_at, NEW.updated_at,
      NEW.creation_origin, NEW.creation_baseline, NEW.creation_baseline_version, NEW.creation_proposal_id, NEW.first_persisted_use_at,
      NEW.creation_reverted_at, NEW.creation_reverted_by_kind, NEW.creation_reverted_by_id, NEW.creation_reversion_notice_id)
    IS DISTINCT FROM ROW(OLD.id, OLD.workspace_id, OLD.project_id, OLD.title, OLD.outcome, OLD.status, OLD.blocker,
      OLD.owner_user_id, OLD.owner_agent_id, OLD.parked_by_decision_id, OLD.parked_at, OLD.created_by_kind, OLD.created_by_id,
      OLD.client_command_id, OLD.request_fingerprint, OLD.criteria, OLD.version, OLD.created_at, OLD.updated_at,
      OLD.creation_origin, OLD.creation_baseline, OLD.creation_baseline_version, OLD.creation_proposal_id, OLD.first_persisted_use_at,
      OLD.creation_reverted_at, OLD.creation_reverted_by_kind, OLD.creation_reverted_by_id, OLD.creation_reversion_notice_id)) THEN
    RAISE EXCEPTION 'reverted task is read only' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: flux_guard_task_creation_receipt(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_guard_task_creation_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'immutable task creation Undo receipt' USING ERRCODE = 'check_violation';
END $$;


--
-- Name: flux_is_sealed(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_is_sealed(value jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
  SELECT coalesce(CASE jsonb_typeof(value)
    WHEN 'string' THEN flux_is_sealed(value #>> '{}')
    WHEN 'object' THEN (SELECT count(*) FROM jsonb_object_keys(value)) = 1 AND jsonb_typeof(value -> '$sealed') = 'string'
      AND flux_is_sealed(value ->> '$sealed')
    ELSE false END, false) $_$;


--
-- Name: flux_is_sealed(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_is_sealed(value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$ SELECT value ~ '^fx1\.[1-9][0-9]{0,8}\.[A-Za-z0-9_-]{38,}$' $_$;


--
-- Name: flux_keep_agent_thread_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_keep_agent_thread_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF NOT EXISTS (SELECT 1 FROM projects WHERE id = OLD.project_id AND workspace_id = OLD.workspace_id) THEN RETURN OLD; END IF;
    -- Guard events and resets belong to their task; boundaries have no task.
    IF TG_TABLE_NAME <> 'agent_thread_artifact_boundaries' THEN
      IF NOT EXISTS (SELECT 1 FROM project_work_items WHERE id = OLD.task_id) THEN RETURN OLD; END IF;
    END IF;
  END IF;
  RAISE EXCEPTION 'Task-thread guard provenance is immutable'
    USING ERRCODE = '23514', CONSTRAINT = 'agent_thread_guard_immutable';
END $$;


--
-- Name: flux_keep_agent_thread_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_keep_agent_thread_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'project_conversations' THEN
    IF (OLD.space = 'agents' OR NEW.space = 'agents') AND
      ROW(OLD.id, OLD.workspace_id, OLD.project_id, OLD.space, OLD.work_id) IS DISTINCT FROM
      ROW(NEW.id, NEW.workspace_id, NEW.project_id, NEW.space, NEW.work_id) THEN
      RAISE EXCEPTION 'Task-thread binding is immutable' USING ERRCODE = '23514', CONSTRAINT = 'agent_thread_guard_identity';
    END IF;
  ELSIF EXISTS (SELECT 1 FROM agent_thread_guard_events WHERE conversation_id = OLD.conversation_id
    OR (TG_OP = 'UPDATE' AND conversation_id = NEW.conversation_id)) THEN
    IF TG_OP = 'DELETE' AND NOT EXISTS (SELECT 1 FROM project_conversations WHERE id = OLD.conversation_id) THEN RETURN OLD; END IF;
    IF TG_OP = 'DELETE' OR ROW(OLD.id, OLD.workspace_id, OLD.project_id, OLD.conversation_id, OLD.author_id, OLD.author_agent_id, OLD.client_message_id)
      IS DISTINCT FROM ROW(NEW.id, NEW.workspace_id, NEW.project_id, NEW.conversation_id, NEW.author_id, NEW.author_agent_id, NEW.client_message_id) THEN
      RAISE EXCEPTION 'Task-thread message identity is immutable' USING ERRCODE = '23514', CONSTRAINT = 'agent_thread_guard_identity';
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: flux_max_version(integer[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_max_version(integer[]) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $_$ SELECT max(v) FROM unnest($1) v $_$;


--
-- Name: flux_notification_content_free(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_notification_content_free() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  ws text;
  sep text;
  who text;
BEGIN
  IF NEW.workspace_id IS NULL OR NOT workspace_sealed(NEW.workspace_id) THEN RETURN NEW; END IF;
  -- A read-state or delivery update keeps the stored text, which was checked when written: a later rename of the
  -- account or the workspace must not make the row impossible to mark read (#712 review P2-1).
  IF TG_OP = 'UPDATE' AND NEW.title IS NOT DISTINCT FROM OLD.title AND NEW.body IS NOT DISTINCT FROM OLD.body
    AND NEW.url IS NOT DISTINCT FROM OLD.url AND NEW.workspace_id = OLD.workspace_id THEN RETURN NEW; END IF;
  -- The link carries ids only: one of the generator's forms with every id replaced (#712 review P3).
  IF NEW.url IS NOT NULL AND regexp_replace(NEW.url, '[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', 'ID', 'g')
    NOT IN ('/inbox', '/projects/ID/conversations/ID#message-ID', '/dm/ID#message-ID', '/projects/ID/tasks?open=work:ID',
      '/projects/ID/tasks?open=decision:ID', '/projects/ID/tasks?open=result:ID', '/projects/ID/live/ID?invitation=ID') THEN
    RAISE EXCEPTION 'An encrypted workspace''s notification must be content-free' USING ERRCODE = 'FX409', HINT = 'NOTIFICATION_CONTENT_REFUSED';
  END IF;
  -- The plain morning summary: a count and a fixed body (#712 review P2-2).
  IF NEW.delivery_kind = 'morning_summary' AND NEW.body = 'Your morning summary from Flux'
    AND NEW.title ~ '^([0-9]{1,4}\+ things wait|1 thing waits|[0-9]{1,4} things wait) in your inbox$' THEN RETURN NEW; END IF;
  SELECT name INTO ws FROM workspaces WHERE id = NEW.workspace_id;
  IF NEW.body = '' THEN
    IF NEW.title = ws || '''s encryption keys were changed outside Flux. It stays locked.' THEN RETURN NEW; END IF;
    IF NEW.title = ws || '''s key change cannot finish yet. Ask your server''s operator.' THEN RETURN NEW; END IF;
    FOREACH sep IN ARRAY ARRAY[' mentioned you in ', ' asked you in ', ' replied in ', ' sent you a message in ', ' assigned you a task in ',
      ' asked for your review in ', ' invited you to work together in ', ' now has an unlock password for '] LOOP
      IF length(NEW.title) > length(sep || ws) AND right(NEW.title, length(sep || ws)) = sep || ws THEN
        who := left(NEW.title, length(NEW.title) - length(sep || ws));
        IF who IN ('Someone', 'An agent') OR EXISTS (SELECT 1 FROM auth_users u WHERE u.name = who) THEN RETURN NEW; END IF;
      END IF;
    END LOOP;
  END IF;
  RAISE EXCEPTION 'An encrypted workspace''s notification must be content-free' USING ERRCODE = 'FX409', HINT = 'NOTIFICATION_CONTENT_REFUSED';
END $_$;


--
-- Name: flux_protect_artifact_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_protect_artifact_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' AND NOT EXISTS (SELECT 1 FROM projects WHERE id = OLD.project_id AND workspace_id = OLD.workspace_id) THEN
    RETURN OLD;
  END IF;
  IF pg_trigger_depth()<2 OR TG_OP='DELETE' THEN
    RAISE EXCEPTION 'Artifact witnesses come only from canonical row mutations'
      USING ERRCODE='23514',CONSTRAINT='agent_thread_artifact_witness';
  END IF;
  NEW.transaction_id:=txid_current();RETURN NEW;
END $$;


--
-- Name: flux_revoke_live_admissions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_revoke_live_admissions() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE live_admissions SET revoked_at = now()
  WHERE auth_session_id = OLD.id AND revoked_at IS NULL;
  IF FOUND THEN
    PERFORM pg_notify('flux_live_admissions', OLD.id);
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: flux_sealed_backstop(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_sealed_backstop() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  r jsonb := to_jsonb(NEW);
  path text[] := string_to_array(TG_ARGV[0], ':');
  ws uuid;
  v jsonb;
BEGIN
  IF path[1] = 'workspace_id' THEN
    ws := (r ->> 'workspace_id')::uuid;
  ELSIF r ->> path[2] IS NOT NULL THEN
    EXECUTE format('SELECT workspace_id FROM %I WHERE %I = $1', path[3], path[4]) INTO ws USING (r ->> path[2])::uuid;
  END IF;
  IF ws IS NULL OR NOT workspace_sealed(ws) THEN RETURN NEW; END IF;
  FOR i IN 1 .. TG_NARGS - 1 LOOP
    v := r -> TG_ARGV[i];
    CONTINUE WHEN v IS NULL OR v = 'null'::jsonb OR v = '""'::jsonb;
    IF flux_is_sealed(v) IS NOT TRUE THEN
      RAISE EXCEPTION 'An encrypted workspace refuses plaintext in %.%', TG_TABLE_NAME, TG_ARGV[i]
        USING ERRCODE = 'FX409', HINT = 'WORKSPACE_PLAINTEXT_REFUSED';
    END IF;
  END LOOP;
  RETURN NEW;
END $_$;


--
-- Name: flux_sealed_wait_ids_only(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_sealed_wait_ids_only() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
BEGIN
  IF NEW.queue ~ '^[a-z][a-z0-9_.-]{0,63}$' AND jsonb_typeof(NEW.payload) = 'object' AND NOT EXISTS (SELECT 1 FROM jsonb_each(NEW.payload) p
      WHERE p.key NOT IN ('eventId', 'resultId') OR jsonb_typeof(p.value) <> 'string'
        OR NOT (p.value #>> '{}') ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$') THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'A sealed job wait carries ids only' USING ERRCODE = 'FX409', HINT = 'EVENT_CONTENT_REFUSED';
END $_$;


--
-- Name: flux_task_criteria_valid(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_task_criteria_valid(criteria jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN jsonb_typeof(criteria) <> 'array' THEN false ELSE
    jsonb_array_length(criteria) <= 20
    AND NOT EXISTS (
      SELECT 1 FROM jsonb_array_elements(criteria) AS item
      WHERE jsonb_typeof(item) <> 'string'
        OR length(item #>> '{}') NOT BETWEEN 1 AND 1000
        OR (item #>> '{}') <> btrim(item #>> '{}', E' \t\r\n'))
    AND (SELECT count(DISTINCT item) FROM jsonb_array_elements(criteria) AS item) = jsonb_array_length(criteria)
  END
$$;


--
-- Name: flux_task_dependency_bound(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_task_dependency_bound() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (SELECT count(*) FROM project_task_dependencies WHERE task_id = NEW.task_id) >= 50 THEN
    RAISE EXCEPTION 'a task has at most 50 prerequisites' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END;
$$;


