-- Name: flux_task_plan_intent_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.flux_task_plan_intent_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
