--
-- Name: guard_map_live_identity(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.guard_map_live_identity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_TABLE_NAME='map_live_object_versions' THEN
    IF ROW(NEW.kind,NEW.object_id,NEW.sketch_id) IS DISTINCT FROM ROW(OLD.kind,OLD.object_id,OLD.sketch_id) OR NEW.version<=OLD.version THEN
      RAISE EXCEPTION 'immutable map object ownership or non-monotonic version' USING ERRCODE='23514';
    END IF;
  ELSIF TG_TABLE_NAME='map_live_heads' THEN
    IF ROW(NEW.sketch_id,NEW.workspace_id,NEW.generation) IS DISTINCT FROM ROW(OLD.sketch_id,OLD.workspace_id,OLD.generation) OR NEW.sequence<OLD.sequence THEN
      RAISE EXCEPTION 'immutable map room or non-monotonic sequence' USING ERRCODE='23514';
    END IF;
  END IF;
  RETURN NEW;
END $$;


--
-- Name: idempotency_scope_required(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.idempotency_scope_required() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.workspace_id IS NULL AND NOT EXISTS (SELECT 1 FROM idempotency_account_operations WHERE operation = NEW.operation) THEN
    RAISE EXCEPTION 'An Idempotency-Key response needs the workspace of its command' USING ERRCODE = 'FX409', HINT = 'IDEMPOTENCY_SCOPE_REQUIRED';
  END IF;
  RETURN NEW;
END $$;


