    AS $$
BEGIN RAISE EXCEPTION 'live editing history and receipts are immutable' USING ERRCODE = 'check_violation'; END $$;


--
-- Name: invalidate_runtime_auth_operations(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.invalidate_runtime_auth_operations() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.state <> 'active' THEN
    UPDATE agent_runtime_auth_operations SET phase = 'uncertain', settled_at = NULL
      WHERE binding_id = NEW.id AND phase = 'active';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: live_replica_ownership_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.live_replica_ownership_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF (NEW.doc_id,NEW.generation,NEW.replica_id,NEW.owner_kind,NEW.actor_id,NEW.instance_id)
    IS DISTINCT FROM (OLD.doc_id,OLD.generation,OLD.replica_id,OLD.owner_kind,OLD.actor_id,OLD.instance_id) THEN
    RAISE EXCEPTION 'live replica ownership is immutable' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: material_agent_doc_stays_doc(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.material_agent_doc_stays_doc() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.kind IS DISTINCT FROM 'doc' AND EXISTS (
    SELECT 1 FROM project_material_versions v WHERE v.material_id = NEW.id AND v.author_agent_id IS NOT NULL) THEN
    RAISE EXCEPTION 'a material with an agent-written version stays a doc'
      USING ERRCODE = 'check_violation', CONSTRAINT = 'project_material_version_agent_doc_parent';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: material_version_agent_doc_parent(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.material_version_agent_doc_parent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  parent_kind text;
BEGIN
  IF NEW.author_agent_id IS NULL THEN RETURN NEW; END IF;
  SELECT pm.kind INTO parent_kind FROM project_materials pm WHERE pm.id = NEW.material_id FOR SHARE;
  IF parent_kind IS DISTINCT FROM 'doc' THEN
    RAISE EXCEPTION 'only a doc version can have an agent author'
      USING ERRCODE = 'check_violation', CONSTRAINT = 'project_material_version_agent_doc_parent';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: preserve_draft_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preserve_draft_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF workspace_sealed(NEW.workspace_id) THEN RETURN NEW; END IF;
  INSERT INTO draft_versions(draft_id, version, title, body, visibility, project_id)
  VALUES (NEW.id, NEW.version, NEW.title, NEW.body, NEW.visibility, NEW.project_id);
  RETURN NEW;
END;
$$;


--
-- Name: project_task_sequence(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_task_sequence(project uuid) RETURNS regclass
    LANGUAGE sql STABLE
    AS $$
  SELECT to_regclass('project_task_number_' || replace(project::text, '-', ''))
$$;


--
-- Name: project_task_sequence_lifecycle(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_task_sequence_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    EXECUTE format('CREATE SEQUENCE %I AS integer', 'project_task_number_' || replace(NEW.id::text, '-', ''));
  ELSE
    EXECUTE format('DROP SEQUENCE IF EXISTS %I', 'project_task_number_' || replace(OLD.id::text, '-', ''));
  END IF;
  RETURN NULL;
END $$;


--
-- Name: project_work_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.project_work_number() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  sequence regclass;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    IF NEW.number IS DISTINCT FROM OLD.number THEN
      RAISE EXCEPTION 'a task number never changes' USING ERRCODE = 'restrict_violation';
    END IF;
    -- The number belongs to the project's sequence: a numbered task never moves to another project.
    IF NEW.project_id IS DISTINCT FROM OLD.project_id THEN
      RAISE EXCEPTION 'a numbered task never moves to another project' USING ERRCODE = 'restrict_violation';
    END IF;
    RETURN NEW;
  END IF;
  sequence := project_task_sequence(NEW.project_id);
  IF sequence IS NULL THEN
    RAISE EXCEPTION 'no task numbering for project %', NEW.project_id USING ERRCODE = 'foreign_key_violation';
  END IF;
  NEW.number := nextval(sequence);
  RETURN NEW;
END $$;


--
-- Name: sealed_workspace_no_ai(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sealed_workspace_no_ai() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  r jsonb := to_jsonb(NEW);
  uuid_text text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  ws uuid;
BEGIN
  IF coalesce(r->>'workspace_id', '') ~* uuid_text THEN
    ws := (r->>'workspace_id')::uuid;
  ELSIF coalesce(r->>'project_id', '') ~* uuid_text THEN
    SELECT workspace_id INTO ws FROM projects WHERE id = (r->>'project_id')::uuid;
  ELSIF coalesce(r->>'agent_id', '') ~* uuid_text THEN
    SELECT workspace_id INTO ws FROM agents WHERE id = (r->>'agent_id')::uuid;
  ELSIF TG_TABLE_NAME LIKE 'agent%' AND coalesce(r->>'connection_id', '') ~* uuid_text THEN
    SELECT workspace_id INTO ws FROM agent_connections WHERE id = (r->>'connection_id')::uuid;
  END IF;
  IF ws IS NOT NULL AND workspace_sealed(ws) THEN
    RAISE EXCEPTION 'AI is always off in an encrypted workspace' USING ERRCODE = 'FX409', HINT = 'WORKSPACE_ENCRYPTED_AI_OFF';
  END IF;
  RETURN NEW;
END $_$;


--
-- Name: sealed_workspace_refused(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sealed_workspace_refused() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$
DECLARE
  r jsonb := to_jsonb(NEW);
  uuid_text text := '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$';
  ws uuid;
BEGIN
  IF coalesce(r ->> 'workspace_id', '') ~* uuid_text THEN
    ws := (r ->> 'workspace_id')::uuid;
  ELSIF coalesce(r ->> 'project_id', '') ~* uuid_text THEN
    SELECT workspace_id INTO ws FROM projects WHERE id = (r ->> 'project_id')::uuid;
  END IF;
  IF ws IS NOT NULL AND workspace_sealed(ws) THEN
    RAISE EXCEPTION 'GitHub is not available in an encrypted workspace' USING ERRCODE = 'FX409', HINT = 'WORKSPACE_ENCRYPTED_UNSUPPORTED';
  END IF;
  RETURN NEW;
END $_$;


--
-- Name: search_change_log(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_change_log() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.sealed THEN INSERT INTO search_changes (workspace_id, doc_key) VALUES (OLD.workspace_id, OLD.doc_key); END IF;
    RETURN OLD;
  END IF;
  IF NEW.sealed THEN INSERT INTO search_changes (workspace_id, doc_key) VALUES (NEW.workspace_id, NEW.doc_key); END IF;
  RETURN NEW;
END $$;


