--
-- Name: search_key(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_key(p_audience text, p_term text) RETURNS bigint
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$ SELECT hashtextextended(p_audience || '|' || p_term, 0) $$;


--
-- Name: search_keys(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_keys(p_audience text, p_title text, p_body text) RETURNS bigint[]
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'public', 'pg_catalog'
    AS $$
  SELECT coalesce(array_agg(DISTINCT search_key(p_audience, k)), '{}')
  FROM (
    SELECT prefixes.k
    FROM (SELECT lexeme FROM unnest(to_tsvector('simple', coalesce(p_title, '') || ' ' || left(coalesce(p_body, ''), 100000)))) words,
    LATERAL (VALUES ('1:' || left(words.lexeme, 1)), (CASE WHEN length(words.lexeme) >= 2 THEN '2:' || left(words.lexeme, 2) END),
      (CASE WHEN length(words.lexeme) >= 3 THEN '3:' || left(words.lexeme, 3) END)) AS prefixes(k)
    UNION ALL
    SELECT 't:' || trigram FROM unnest(show_trgm(left(coalesce(p_title, ''), 1000))) AS trigram
  ) keys
  WHERE k IS NOT NULL
$$;


--
-- Name: search_put(text, text, uuid, text, uuid, text, uuid, integer, text, text, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_put(p_key text, p_kind text, p_workspace uuid, p_audience text, p_project uuid, p_object text, p_parent uuid, p_version integer, p_status text, p_title text, p_body text, p_author_kind text, p_author text, p_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE placeholder boolean := p_kind <> 'person' AND workspace_sealed(p_workspace);
BEGIN
  INSERT INTO search_documents(doc_key, kind, workspace_id, audience_key, project_id, object_id, parent_id, version, status, title, body, author_kind, author_id, at, sealed)
  VALUES (p_key, p_kind, p_workspace, p_audience, p_project, p_object, p_parent, p_version, p_status,
    CASE WHEN placeholder THEN '' ELSE coalesce(p_title, '') END, CASE WHEN placeholder THEN '' ELSE coalesce(p_body, '') END,
    p_author_kind, p_author, p_at, placeholder)
  ON CONFLICT (doc_key) DO UPDATE SET
    workspace_id = EXCLUDED.workspace_id, audience_key = EXCLUDED.audience_key, project_id = EXCLUDED.project_id,
    parent_id = EXCLUDED.parent_id, version = EXCLUDED.version, status = EXCLUDED.status, title = EXCLUDED.title,
    body = EXCLUDED.body, author_kind = EXCLUDED.author_kind, author_id = EXCLUDED.author_id, at = EXCLUDED.at, sealed = EXCLUDED.sealed;
END $$;


--
-- Name: search_term(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.search_term(p_lexeme text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$ SELECT least(length(p_lexeme), 3)::text || ':' || left(p_lexeme, 3) $$;


--
-- Name: workspace_ai_policy_create(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workspace_ai_policy_create() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO workspace_ai_policies (workspace_id, state) VALUES (NEW.id, CASE WHEN NEW.encrypted THEN 'blocked' ELSE 'allowed' END);
  RETURN NEW;
END $$;


--
-- Name: workspace_ai_policy_encrypted(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workspace_ai_policy_encrypted() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF NEW.state = 'allowed' AND workspace_sealed(NEW.workspace_id) THEN
    RAISE EXCEPTION 'AI is always off in an encrypted workspace' USING ERRCODE = 'FX409', HINT = 'WORKSPACE_ENCRYPTED_AI_OFF';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: workspace_encryption_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workspace_encryption_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.encrypted IS DISTINCT FROM OLD.encrypted THEN
    RAISE EXCEPTION 'A workspace''s encryption is chosen at creation and cannot change' USING ERRCODE = 'FX409', HINT = 'WORKSPACE_ENCRYPTION_IMMUTABLE';
  END IF;
  RETURN NEW;
END $$;


--
-- Name: workspace_holder_delete_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workspace_holder_delete_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.kind = 'password' AND EXISTS (SELECT 1 FROM workspaces WHERE id = OLD.workspace_id)
    AND NOT EXISTS (SELECT 1 FROM workspace_holders WHERE workspace_id = OLD.workspace_id AND kind = 'password' AND id <> OLD.id) THEN
    RAISE EXCEPTION 'The workspace needs at least one unlock password' USING ERRCODE = 'FX409', HINT = 'LAST_UNLOCK_PASSWORD';
  END IF;
  RETURN OLD;
END $$;


--
-- Name: workspace_holder_deleted(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workspace_holder_deleted() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM workspace_keys WHERE workspace_id = OLD.workspace_id) THEN
    INSERT INTO workspace_removed_holders (workspace_id, holder_id, user_id, public_key)
      VALUES (OLD.workspace_id, OLD.id, OLD.user_id, OLD.public_key) ON CONFLICT DO NOTHING;
    UPDATE workspace_keys SET rotation = 'pending', rotation_reason = jsonb_build_object('kind', 'holder_deleted', 'userId', OLD.user_id)
      WHERE workspace_id = OLD.workspace_id AND rotation IN ('none', 'reencrypting');
  END IF;
  RETURN NULL;
END $$;


--
-- Name: workspace_manager_lost(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workspace_manager_lost() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF OLD.role IN ('owner', 'admin') AND (TG_OP = 'DELETE' OR NEW.role NOT IN ('owner', 'admin'))
    AND EXISTS (SELECT 1 FROM workspaces WHERE id = OLD.workspace_id AND encrypted)
    AND EXISTS (SELECT 1 FROM workspace_keys WHERE workspace_id = OLD.workspace_id) THEN
    DELETE FROM workspace_holders WHERE workspace_id = OLD.workspace_id
      AND (kind = 'recovery' OR (kind = 'password' AND user_id = OLD.user_id));
    UPDATE workspace_keys SET rotation = 'pending',
      rotation_reason = jsonb_build_object('kind', CASE WHEN TG_OP = 'DELETE' THEN 'removed' ELSE 'demoted' END, 'userId', OLD.user_id)
      WHERE workspace_id = OLD.workspace_id;
  END IF;
  RETURN NULL;
END $$;


--
-- Name: workspace_sealed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.workspace_sealed(uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $_$ SELECT coalesce((SELECT encrypted FROM workspaces WHERE id = $1), false) $_$;


--
-- Name: agent_command_receipts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_command_receipts (
    connection_id uuid NOT NULL,
    client_command_id uuid NOT NULL,
    runtime_session_id uuid NOT NULL,
    grant_id uuid NOT NULL,
    grant_generation integer NOT NULL,
    binding_id uuid NOT NULL,
    binding_generation integer NOT NULL,
    fingerprint text NOT NULL,
    operation text NOT NULL,
    project_id uuid NOT NULL,
    value jsonb NOT NULL,
    postconditions jsonb NOT NULL,
    completed_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT agent_command_receipts_binding_generation_check CHECK ((binding_generation > 0)),
    CONSTRAINT agent_command_receipts_fingerprint_check CHECK ((length(fingerprint) = 64)),
    CONSTRAINT agent_command_receipts_grant_generation_check CHECK ((grant_generation > 0)),
    CONSTRAINT agent_command_receipts_postconditions_check CHECK ((jsonb_typeof(postconditions) = 'array'::text))
);


