    version integer DEFAULT 1 NOT NULL,
    enabled_capability_ids text[] NOT NULL,
    enabled_entry_ids text[] NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT agent_connection_mcp_capability_array_check CHECK (((cardinality(enabled_capability_ids) <= 128) AND (array_position(enabled_capability_ids, NULL::text) IS NULL))),
    CONSTRAINT agent_connection_mcp_entry_array_check CHECK (((cardinality(enabled_entry_ids) <= 256) AND (array_position(enabled_entry_ids, NULL::text) IS NULL))),
    CONSTRAINT agent_connection_mcp_policy_version_check CHECK ((version > 0))
);


