--
-- Name: agent_connections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_connections (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    owner_user_id text NOT NULL,
    agent_id uuid NOT NULL,
    scopes text[] NOT NULL,
    revoked_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    name text DEFAULT 'External connection'::text NOT NULL,
    client_designation text DEFAULT 'other'::text NOT NULL,
    compute_source text DEFAULT 'user_operated_external_client'::text NOT NULL,
    CONSTRAINT agent_connections_client_designation_check CHECK ((client_designation = ANY (ARRAY['claude_code'::text, 'codex'::text, 'other'::text]))),
    CONSTRAINT agent_connections_compute_source_check CHECK ((compute_source = ANY (ARRAY['user_operated_claude_code'::text, 'user_operated_external_client'::text, 'owner_assistant'::text]))),
    CONSTRAINT agent_connections_name_check CHECK (((length(btrim(name)) >= 1) AND (length(btrim(name)) <= 120))),
    CONSTRAINT agent_connections_scopes_check CHECK (((cardinality(scopes) BETWEEN 1 AND 3) AND (scopes <@ ARRAY['flux.context.read'::text, 'flux.proposal.write'::text, 'flux.action.execute'::text])))
);


--
-- Name: agent_oauth_bindings; Type: TABLE; Schema: public; Owner: -
--

