    CONSTRAINT agent_runtime_auth_operations_operation_id_check CHECK (((operation_id)::text ~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'::text)),
    CONSTRAINT agent_runtime_auth_operations_phase_check CHECK ((phase = ANY (ARRAY['active'::text, 'settled'::text, 'uncertain'::text]))),
    CONSTRAINT agent_runtime_auth_operations_revision_check CHECK ((revision > 0))
);


