    CONSTRAINT agent_runtime_bindings_release_check CHECK ((((state = ANY (ARRAY['releasing'::text, 'released'::text])) = (release_reason IS NOT NULL)) AND ((release_reason IS NULL) = (release_requested_at IS NULL)) AND ((state = 'released'::text) = (released_at IS NOT NULL)) AND ((state = 'released'::text) OR (release_logout_failed IS NULL)))),
    CONSTRAINT agent_runtime_bindings_release_reason_check CHECK ((release_reason = ANY (ARRAY['owner'::text, 'operator'::text, 'idle'::text, 'purge'::text, 'bind_failed'::text, 'auth_recovery'::text]))),
    CONSTRAINT agent_runtime_bindings_state_check CHECK ((state = ANY (ARRAY['binding'::text, 'active'::text, 'sign_in_again'::text, 'releasing'::text, 'released'::text])))
);


