--
-- Name: agent_runtime_connections; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.agent_runtime_connections (
    id uuid NOT NULL,
    owner_user_id text NOT NULL,
    binding_id uuid NOT NULL,
    transport text DEFAULT 'runtime'::text NOT NULL,
    client text NOT NULL,
    state text NOT NULL,
    sign_in_method text,
    auth_method text,
    plan_label text,
    account_label text,
    signed_in_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    revoked_at timestamp with time zone,
    account_fingerprint text,
    previous_account_label text,
    account_changed_at timestamp with time zone,
    signed_out_at timestamp with time zone,
    sign_out_failed boolean,
    CONSTRAINT agent_runtime_connections_account_label_check CHECK ((account_label ~ '^[A-Za-z0-9*]\*\*\*@[A-Za-z0-9.*-]{1,70}$'::text)),
    CONSTRAINT agent_runtime_connections_auth_method_check CHECK ((auth_method ~ '^[a-z][a-z0-9_.-]{0,31}$'::text)),
    CONSTRAINT agent_runtime_connections_client_check CHECK ((client = ANY (ARRAY['claude_code'::text, 'codex'::text]))),
    CONSTRAINT agent_runtime_connections_codex_method_check CHECK (((client <> 'codex'::text) OR (sign_in_method IS NULL) OR (sign_in_method = ANY (ARRAY['device_code'::text, 'api_key'::text, 'access_token'::text])))),
    CONSTRAINT agent_runtime_connections_fingerprint_check CHECK ((account_fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT agent_runtime_connections_method_check CHECK (((client <> 'claude_code'::text) OR (sign_in_method IS NULL) OR (sign_in_method = ANY (ARRAY['claude_account'::text, 'console'::text, 'sso'::text])))),
    CONSTRAINT agent_runtime_connections_notice_check CHECK (((account_changed_at IS NOT NULL) OR (previous_account_label IS NULL))),
    CONSTRAINT agent_runtime_connections_plan_label_check CHECK (((length(plan_label) <= 40) AND (plan_label ~ '^[A-Za-z0-9][A-Za-z0-9 ._+-]*$'::text))),
    CONSTRAINT agent_runtime_connections_previous_label_check CHECK ((previous_account_label ~ '^[A-Za-z0-9*]\*\*\*@[A-Za-z0-9.*-]{1,70}$'::text)),
    CONSTRAINT agent_runtime_connections_revoked_check CHECK (((revoked_at IS NULL) OR (state <> 'signed_in'::text))),
    CONSTRAINT agent_runtime_connections_sign_in_method_check CHECK ((sign_in_method = ANY (ARRAY['claude_account'::text, 'console'::text, 'sso'::text, 'device_code'::text, 'api_key'::text, 'access_token'::text]))),
    CONSTRAINT agent_runtime_connections_sign_out_check CHECK (((signed_out_at IS NULL) = (sign_out_failed IS NULL))),
    CONSTRAINT agent_runtime_connections_signed_in_check CHECK (((state = 'signed_in'::text) = (signed_in_at IS NOT NULL))),
    CONSTRAINT agent_runtime_connections_state_check CHECK ((state = ANY (ARRAY['signed_out'::text, 'signed_in'::text, 'sign_in_again'::text]))),
    CONSTRAINT agent_runtime_connections_transport_check CHECK ((transport = 'runtime'::text))
);


