--
-- Name: cowork_requests; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.cowork_requests (
    id uuid NOT NULL,
    lineage_id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    project_id uuid NOT NULL,
    work_id uuid NOT NULL,
    unit_id uuid NOT NULL,
    sender_connection_id uuid NOT NULL,
    recipient_connection_id uuid NOT NULL,
    sender_owner_id text NOT NULL,
    recipient_owner_id text NOT NULL,
    intent_key text NOT NULL,
    fingerprint text NOT NULL,
    parent_request_id uuid,
    kind text NOT NULL,
    target jsonb NOT NULL,
    source_refs jsonb NOT NULL,
    criteria_refs jsonb NOT NULL,
    depth integer NOT NULL,
    review_round integer NOT NULL,
    priority integer NOT NULL,
    peer_unblocking boolean NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    state text DEFAULT 'queued'::text NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    reason text,
    next_boundary text,
    dependency_ref jsonb,
    claimed_generation integer,
    response_ref jsonb,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    cancelled_by text,
    ai_epoch bigint NOT NULL,
    CONSTRAINT cowork_requests_check CHECK ((((parent_request_id IS NULL) AND (depth = 0)) OR ((parent_request_id IS NOT NULL) AND (depth > 0)))),
    CONSTRAINT cowork_requests_check1 CHECK (((state <> 'deferred'::text) OR ((reason IS NOT NULL) AND (next_boundary IS NOT NULL)))),
    CONSTRAINT cowork_requests_check2 CHECK (((state <> 'deferred'::text) OR (reason <> 'dependency'::text) OR ((dependency_ref IS NOT NULL) AND (jsonb_typeof(dependency_ref) = 'object'::text)))),
    CONSTRAINT cowork_requests_check3 CHECK (((state <> 'claimed'::text) OR ((claimed_generation IS NOT NULL) AND (claimed_generation > 0)))),
    CONSTRAINT cowork_requests_check4 CHECK (((state <> 'resolved'::text) OR ((response_ref IS NOT NULL) AND (jsonb_typeof(response_ref) = 'object'::text)))),
    CONSTRAINT cowork_requests_check5 CHECK (((state <> ALL (ARRAY['declined'::text, 'superseded'::text, 'expired'::text, 'cancelled'::text])) OR (reason IS NOT NULL))),
    CONSTRAINT cowork_requests_criteria_refs_check CHECK (((jsonb_typeof(criteria_refs) = 'array'::text) AND ((jsonb_array_length(criteria_refs) >= 1) AND (jsonb_array_length(criteria_refs) <= 8)) AND (octet_length((criteria_refs)::text) <= 8192))),
    CONSTRAINT cowork_requests_depth_check CHECK (((depth >= 0) AND (depth <= 8))),
    CONSTRAINT cowork_requests_fingerprint_check CHECK ((fingerprint ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT cowork_requests_intent_key_check CHECK (((length(intent_key) >= 1) AND (length(intent_key) <= 200))),
    CONSTRAINT cowork_requests_kind_check CHECK ((kind = ANY (ARRAY['help'::text, 'review'::text, 'fix'::text, 'handoff'::text]))),
    CONSTRAINT cowork_requests_priority_check CHECK (((priority >= 0) AND (priority <= 3))),
    CONSTRAINT cowork_requests_review_round_check CHECK (((review_round >= 0) AND (review_round <= 16))),
    CONSTRAINT cowork_requests_source_refs_check CHECK (((jsonb_typeof(source_refs) = 'array'::text) AND ((jsonb_array_length(source_refs) >= 1) AND (jsonb_array_length(source_refs) <= 16)) AND (octet_length((source_refs)::text) <= 16384))),
    CONSTRAINT cowork_requests_state_check CHECK ((state = ANY (ARRAY['queued'::text, 'deferred'::text, 'claimed'::text, 'resolved'::text, 'declined'::text, 'superseded'::text, 'expired'::text, 'cancelled'::text]))),
    CONSTRAINT cowork_requests_target_check CHECK (((jsonb_typeof(target) = 'object'::text) AND (octet_length((target)::text) <= 1024))),
    CONSTRAINT cowork_requests_version_check CHECK ((version > 0))
);


