    ai_epoch bigint NOT NULL,
    CONSTRAINT cowork_units_check CHECK ((((state = 'claimed'::text) AND (generation > 0) AND (lease_id IS NOT NULL) AND (lease_session_id IS NOT NULL) AND ((length(lease_session_id) >= 1) AND (length(lease_session_id) <= 255)) AND (lease_expires_at IS NOT NULL)) OR ((state <> 'claimed'::text) AND (lease_id IS NULL) AND (lease_session_id IS NULL) AND (lease_expires_at IS NULL)))),
    CONSTRAINT cowork_units_generation_check CHECK ((generation >= 0)),
    CONSTRAINT cowork_units_outcome_check CHECK (((outcome_ref IS NULL) OR ((state = 'completed'::text) AND (jsonb_typeof(outcome_ref) = 'object'::text) AND ((outcome_ref ->> 'type'::text) = ANY (ARRAY['result'::text, 'message'::text, 'material'::text, 'doc'::text, 'work'::text, 'thought'::text])) AND (octet_length((outcome_ref)::text) <= 1024)))),
    CONSTRAINT cowork_units_role_check CHECK ((role = ANY (ARRAY['execute'::text, 'review'::text, 'plan'::text]))),
    CONSTRAINT cowork_units_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'claimed'::text, 'paused'::text, 'completed'::text, 'stopped'::text]))),
    CONSTRAINT cowork_units_unit_key_check CHECK (((length(unit_key) >= 1) AND (length(unit_key) <= 200))),
    CONSTRAINT cowork_units_version_check CHECK ((version > 0))
);


