    CONSTRAINT personal_run_enablements_status_check CHECK ((status = ANY (ARRAY['active'::text, 'paused'::text]))),
    CONSTRAINT personal_run_enablements_time_zone_check CHECK (((length(time_zone) >= 1) AND (length(time_zone) <= 64))),
    CONSTRAINT personal_run_enablements_version_check CHECK ((version > 0))
);


