    CONSTRAINT personal_runs_engine_check CHECK ((engine = ANY (ARRAY['server'::text, 'runtime'::text]))),
    CONSTRAINT personal_runs_input_tokens_check CHECK ((input_tokens >= 0)),
    CONSTRAINT personal_runs_kind_check CHECK ((kind = ANY (ARRAY['ask'::text, 'summarize'::text, 'map_thought'::text, 'scheduled'::text, 'morning_summary'::text, 'reaction'::text]))),
    CONSTRAINT personal_runs_mcp_limit_check CHECK ((mcp_limit = ANY (ARRAY['call'::text, 'run'::text]))),
