    CONSTRAINT personal_runs_reserved_micros_check CHECK (((reserved_micros > 0) OR ((engine = 'runtime'::text) AND (reserved_micros = 0)))),
    CONSTRAINT personal_runs_run_token_check CHECK (((run_token_jti IS NULL) = (run_token_expires_at IS NULL))),
    CONSTRAINT personal_runs_run_token_nonce_hash_check CHECK ((run_token_nonce_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT personal_runs_run_tools_check CHECK ((cardinality(run_tools) <= 64)),
    CONSTRAINT personal_runs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'reading'::text, 'dispatching'::text, 'completed'::text, 'truncated'::text, 'stopped'::text, 'denied'::text, 'paused'::text, 'revoked'::text, 'cap_reached'::text, 'unavailable'::text, 'input_too_large'::text, 'provider_failed'::text]))),
    CONSTRAINT personal_runs_stopped_at_stage_check CHECK ((stopped_at_stage = ANY (ARRAY['before_read'::text, 'before_dispatch'::text, 'before_commit'::text])))
);


