    supersedes_id uuid,
    superseded_by_id uuid,
    superseded_at timestamp with time zone,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT project_decisions_check CHECK (((status = 'proposed'::text) = (decided_by IS NULL))),
    CONSTRAINT project_decisions_check1 CHECK (((decided_by IS NULL) = (decided_at IS NULL))),
    CONSTRAINT project_decisions_check2 CHECK (((status = 'superseded'::text) = (superseded_by_id IS NOT NULL))),
    CONSTRAINT project_decisions_check3 CHECK (((superseded_by_id IS NULL) = (superseded_at IS NULL))),
    CONSTRAINT project_decisions_check4 CHECK (((supersedes_id IS NULL) OR (supersedes_id <> id))),
    CONSTRAINT project_decisions_proposed_by_kind_check CHECK ((proposed_by_kind = ANY (ARRAY['human'::text, 'agent'::text]))),
    CONSTRAINT project_decisions_rationale_check CHECK ((public.flux_is_sealed(rationale) OR (length(rationale) <= 20000))),
    CONSTRAINT project_decisions_status_check CHECK ((status = ANY (ARRAY['proposed'::text, 'accepted'::text, 'superseded'::text]))),
    CONSTRAINT project_decisions_title_check CHECK ((public.flux_is_sealed(title) OR ((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 200)))),
    CONSTRAINT project_decisions_version_check CHECK ((version > 0))
);


