    upload_id uuid NOT NULL,
    replay_of uuid,
    name text NOT NULL,
    state text NOT NULL,
    reserved_bytes integer NOT NULL,
    size integer,
    sha256 text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    ready_at timestamp with time zone,
    expires_at timestamp with time zone,
    message_id uuid,
    "position" smallint,
    published_at timestamp with time zone,
    thought_id uuid,
    key_version integer,
    page_count integer,
    row_count integer,
    duration_ms integer,
    CONSTRAINT project_file_exact_uploader CHECK ((num_nonnulls(uploader_id, uploader_agent_id) = 1)),
    CONSTRAINT project_file_publication CHECK ((((message_id IS NULL) = ("position" IS NULL)) AND (num_nonnulls(message_id, thought_id) <= 1) AND ((num_nonnulls(message_id, thought_id) = 1) = (published_at IS NOT NULL)))),
    CONSTRAINT project_file_published_ready CHECK (((published_at IS NULL) OR ((state = 'ready'::text) AND (expires_at IS NULL)))),
    CONSTRAINT project_file_ready_identity CHECK (((state = 'ready'::text) = ((size IS NOT NULL) AND (sha256 IS NOT NULL) AND (ready_at IS NOT NULL)))),
    CONSTRAINT project_file_replay_receiving CHECK (((replay_of IS NULL) OR ((state = 'receiving'::text) AND (published_at IS NULL)))),
    CONSTRAINT project_file_unpublished_expires CHECK (((published_at IS NOT NULL) OR (expires_at IS NOT NULL))),
    CONSTRAINT project_files_check CHECK (((reserved_bytes BETWEEN 0 AND 5242880) AND ((reserved_bytes > 0) OR (replay_of IS NOT NULL)))),
    CONSTRAINT project_files_duration_ms_check CHECK (((duration_ms IS NULL) OR (duration_ms >= 0))),
    CONSTRAINT project_files_key_version_check CHECK (((key_version IS NULL) OR (key_version >= 1))),
    CONSTRAINT project_files_name_check CHECK ((public.flux_is_sealed(name) OR ((char_length(name) >= 1) AND (char_length(name) <= 200)))),
    CONSTRAINT project_files_page_count_check CHECK (((page_count IS NULL) OR (page_count >= 0))),
    CONSTRAINT project_files_position_check CHECK ((("position" >= 0) AND ("position" <= 9))),
    CONSTRAINT project_files_row_count_check CHECK (((row_count IS NULL) OR (row_count >= 0))),
    CONSTRAINT project_files_sha256_check CHECK ((public.flux_is_sealed(sha256) OR (sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT project_files_size_check CHECK (((size >= 1) AND (size <= 5242880))),
    CONSTRAINT project_files_state_check CHECK ((state = ANY (ARRAY['receiving'::text, 'ready'::text])))
);


