    CONSTRAINT project_work_items_check1 CHECK (((owner_user_id IS NULL) OR (owner_agent_id IS NULL))),
    CONSTRAINT project_work_items_check2 CHECK (((parked_by_decision_id IS NULL) = (parked_at IS NULL))),
    CONSTRAINT project_work_items_check3 CHECK (((parked_at IS NULL) OR (status <> ALL (ARRAY['done'::text, 'not_pursued'::text])))),
    CONSTRAINT project_work_items_created_by_kind_check CHECK ((created_by_kind = ANY (ARRAY['human'::text, 'agent'::text]))),
    CONSTRAINT project_work_items_creation_baseline_version_check CHECK ((creation_baseline_version > 0)),
    CONSTRAINT project_work_items_creation_origin_check CHECK ((creation_origin = ANY (ARRAY['native_agent'::text, 'ai_proposal'::text, 'human'::text]))),
    CONSTRAINT project_work_items_creation_reverted_by_kind_check CHECK ((creation_reverted_by_kind = ANY (ARRAY['human'::text, 'agent'::text]))),
    CONSTRAINT project_work_items_due_on_range CHECK (((due_on IS NULL) OR ((due_on >= '1970-01-01'::date) AND (due_on <= '9999-12-31'::date)))),
    CONSTRAINT project_work_items_outcome_check CHECK ((public.flux_is_sealed(outcome) OR (length(outcome) <= 4000))),
    CONSTRAINT project_work_items_status_check CHECK ((status = ANY (ARRAY['open'::text, 'in_progress'::text, 'blocked'::text, 'done'::text, 'not_pursued'::text]))),
    CONSTRAINT project_work_items_title_check CHECK ((public.flux_is_sealed(title) OR ((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 200)))),
    CONSTRAINT project_work_items_version_check CHECK ((version > 0)),
    CONSTRAINT task_creation_baseline_origin CHECK ((((creation_baseline_version IS NULL) = (creation_origin IS NULL)) AND ((creation_baseline IS NULL) = (creation_origin IS NULL)))),
    CONSTRAINT task_creation_proposal_origin CHECK ((((creation_origin IS NULL) AND (creation_proposal_id IS NULL)) OR ((creation_origin IS NOT NULL) AND ((creation_origin = 'ai_proposal'::text) = (creation_proposal_id IS NOT NULL))))),
    CONSTRAINT task_creation_reversion_shape CHECK ((((creation_reverted_at IS NULL) AND (creation_reverted_by_kind IS NULL) AND (creation_reverted_by_id IS NULL) AND (creation_reversion_notice_id IS NULL)) OR ((creation_reverted_at IS NOT NULL) AND (creation_reverted_by_kind IS NOT NULL) AND (creation_reverted_by_id IS NOT NULL) AND (creation_reversion_notice_id IS NOT NULL) AND (creation_baseline_version IS NOT NULL) AND (creation_origin = ANY (ARRAY['native_agent'::text, 'ai_proposal'::text, 'human'::text])) AND (first_persisted_use_at IS NULL))))
);


