--
-- Name: search_documents; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.search_documents (
    id bigint NOT NULL,
    doc_key text NOT NULL,
    kind text NOT NULL,
    workspace_id uuid NOT NULL,
    audience_key text NOT NULL,
    project_id uuid,
    object_id text NOT NULL,
    parent_id uuid,
    version integer,
    status text,
    title text DEFAULT ''::text NOT NULL,
    body text DEFAULT ''::text NOT NULL,
    author_kind text,
    author_id text,
    at timestamp with time zone NOT NULL,
    tsv tsvector GENERATED ALWAYS AS ((setweight(to_tsvector('simple'::regconfig, title), 'A'::"char") || setweight(to_tsvector('simple'::regconfig, "left"(body, 100000)), 'B'::"char"))) STORED,
    keys bigint[] GENERATED ALWAYS AS (public.search_keys(audience_key, title, body)) STORED,
    dm_id uuid,
    sealed boolean DEFAULT false NOT NULL,
    CONSTRAINT search_documents_author_kind_check CHECK ((author_kind = ANY (ARRAY['human'::text, 'agent'::text]))),
    CONSTRAINT search_documents_kind_check CHECK ((kind = ANY (ARRAY['project'::text, 'message'::text, 'dm_message'::text, 'material'::text, 'doc'::text, 'work'::text, 'decision'::text, 'result'::text, 'sketch'::text, 'thought'::text, 'draft'::text, 'person'::text]))),
    CONSTRAINT search_documents_sealed_placeholder CHECK (((NOT sealed) OR ((title = ''::text) AND (body = ''::text))))
);


