--
-- Name: sketch_links; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sketch_links (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    sketch_id uuid NOT NULL,
    from_id uuid NOT NULL,
    to_id uuid NOT NULL,
    label text,
    created_by_user_id text,
    created_by_agent_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT sketch_links_check CHECK ((from_id <> to_id)),
    CONSTRAINT sketch_links_check1 CHECK (((created_by_user_id IS NULL) <> (created_by_agent_id IS NULL))),
    CONSTRAINT sketch_links_label_check CHECK ((public.flux_is_sealed(label) OR ((label IS NULL) OR ((length(btrim(label)) >= 1) AND (length(btrim(label)) <= 80)))))
);


--
-- Name: sketch_thoughts; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sketch_thoughts (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    sketch_id uuid NOT NULL,
    text text NOT NULL,
    x integer NOT NULL,
    y integer NOT NULL,
    width integer DEFAULT 184 NOT NULL,
    height integer DEFAULT 72 NOT NULL,
    shape text DEFAULT 'card'::text NOT NULL,
    placement_type text,
    placement_id uuid,
    created_by_user_id text,
    created_by_agent_id uuid,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    source_author_id text,
    source_author_name text,
    source_sent_at timestamp with time zone,
    source_dm_id uuid,
    source_message_id uuid,
    source_author_agent_id uuid,
    source_project_message_id uuid,
    CONSTRAINT sketch_thoughts_check CHECK (((placement_type IS NULL) = (placement_id IS NULL))),
    CONSTRAINT sketch_thoughts_check1 CHECK (((created_by_user_id IS NULL) <> (created_by_agent_id IS NULL))),
    CONSTRAINT sketch_thoughts_height_check CHECK (((height >= 40) AND (height <= 800))),
    CONSTRAINT sketch_thoughts_placement_type_check CHECK ((placement_type = 'draft'::text)),
    CONSTRAINT sketch_thoughts_shape_check CHECK ((shape = ANY (ARRAY['card'::text, 'pill'::text, 'circle'::text]))),
    CONSTRAINT sketch_thoughts_source_author_kind_check CHECK ((num_nonnulls(source_author_id, source_author_agent_id) = ANY (ARRAY[0, 1]))),
    CONSTRAINT sketch_thoughts_source_dm_project_check CHECK (((source_project_message_id IS NULL) OR ((source_dm_id IS NULL) AND (source_message_id IS NULL) AND (source_sent_at IS NOT NULL) AND (num_nonnulls(source_author_id, source_author_agent_id) = 1)))),
    CONSTRAINT sketch_thoughts_source_message_check CHECK ((((source_dm_id IS NULL) = (source_message_id IS NULL)) AND ((source_message_id IS NULL) OR (source_author_id IS NOT NULL)))),
    CONSTRAINT sketch_thoughts_source_presence_check CHECK ((((source_sent_at IS NULL) = (source_author_name IS NULL)) AND ((source_sent_at IS NULL) = (num_nonnulls(source_author_id, source_author_agent_id) = 0)))),
    CONSTRAINT sketch_thoughts_text_check CHECK ((public.flux_is_sealed(text) OR ((length(btrim(text)) >= 1) AND (length(btrim(text)) <= 1000)))),
    CONSTRAINT sketch_thoughts_version_check CHECK ((version >= 1)),
    CONSTRAINT sketch_thoughts_width_check CHECK (((width >= 80) AND (width <= 800))),
    CONSTRAINT sketch_thoughts_x_check CHECK (((x >= '-100000'::integer) AND (x <= 100000))),
    CONSTRAINT sketch_thoughts_y_check CHECK (((y >= '-100000'::integer) AND (y <= 100000)))
);


--
-- Name: sketches; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.sketches (
    id uuid NOT NULL,
    workspace_id uuid NOT NULL,
    scope text NOT NULL,
    project_id uuid,
    title text NOT NULL,
    created_by_user_id text,
    created_by_agent_id uuid,
