    dm_id uuid,
    copied_from_sketch_id uuid,
    copied_by_user_id text,
    copied_at timestamp with time zone,
    CONSTRAINT sketches_check CHECK (((scope = 'project'::text) = (project_id IS NOT NULL))),
    CONSTRAINT sketches_check1 CHECK (((scope <> 'private'::text) OR (created_by_user_id IS NOT NULL))),
    CONSTRAINT sketches_check2 CHECK (((created_by_user_id IS NULL) <> (created_by_agent_id IS NULL))),
    CONSTRAINT sketches_copy_check CHECK (((copied_by_user_id IS NULL) = (copied_at IS NULL))),
    CONSTRAINT sketches_copy_scope_check CHECK (((copied_at IS NULL) OR (scope = 'project'::text))),
    CONSTRAINT sketches_dm_person_check CHECK (((scope <> 'dm'::text) OR (created_by_user_id IS NOT NULL))),
    CONSTRAINT sketches_dm_scope_check CHECK (((scope = 'dm'::text) = (dm_id IS NOT NULL))),
    CONSTRAINT sketches_scope_check CHECK ((scope = ANY (ARRAY['project'::text, 'private'::text, 'dm'::text]))),
    CONSTRAINT sketches_title_check CHECK ((public.flux_is_sealed(title) OR ((length(btrim(title)) >= 1) AND (length(btrim(title)) <= 200)))),
    CONSTRAINT sketches_version_check CHECK ((version >= 1))
);


